18	// The MHPCO price list: one row per insurable item type, stating that type's
19	// insurance value and base premium. The spec lists both figures together
20	// ("Amulet: 600 G / 60 G"), and the set of rows is one piece of knowledge --
21	// a type MHPCO will not price is a type it will not insure.
22	interface PriceListEntry {
23	  insuranceValue: number;
24	  basePremium: number;
25	}
26	
27	const PRICE_LIST: Record<string, PriceListEntry> = {
28	  sword: { insuranceValue: 1000, basePremium: 100 },
29	  amulet: { insuranceValue: 600, basePremium: 60 },
30	  staff: { insuranceValue: 800, basePremium: 80 },
31	  potion: { insuranceValue: 400, basePremium: 40 },
32	  rune: { insuranceValue: 250, basePremium: 25 },
33	  moonstone: { insuranceValue: 250, basePremium: 25 },
34	};
35	
36	// The only two places that know how the price list is stored; pricing and
37	// claim policies ask for a type's listed figure rather than indexing.
38	function listedEntry(type: string): PriceListEntry {
39	  const entry = PRICE_LIST[type];
40	  if (entry === undefined) {
41	    throw new Error(`MHPCO does not insure items of type "${type}"`);
42	  }
43	  return entry;
44	}
45	
46	function listedBasePremium(type: string): number {
47	  return listedEntry(type).basePremium;
48	}
49	
50	function listedInsuranceValue(type: string): number {
51	  return listedEntry(type).insuranceValue;
52	}
