54	// --- MHPCO claim rulebook: what a damage report is owed ------------------
55	
56	// A reported damage, and the incident that reports it. These are MHPCO's
57	// vocabulary for a claim, not a transport shape: the clause, deductible and
58	// cap decisions below are all stated in terms of them.
59	export interface Damage {
60	  itemType: string;
61	  amount: number;
62	}
63	
64	export interface Incident {
65	  cause: string;
66	  damages: Damage[];
67	}
