69	const DEDUCTIBLE_PER_DAMAGE = 100;
70	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
71	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
72	const DRAGON_MATERIAL = "dragon";
73	const DRAGON_MATERIAL_REIMBURSEMENT_RATE = 1;
74	const NO_CLAUSE_REIMBURSEMENT_RATE = 1;
75	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
76	
77	// --- MHPCO premium rulebook: what a policy costs to write ----------------
78	
79	const CURSE_SURCHARGE_RATE = 0.5;
80	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
81	const HIGH_ENCHANTMENT_THRESHOLD = 5;
82	const COMPONENT_BLOCK_SIZE = 3;
83	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
84	
85	// "Alike" means the same item type: 2 runes + 1 moonstone form no block,
86	// while 3 runes + 3 moonstones form two separate blocks.
87	function groupAlikeItems(items: Item[]): Map<string, number> {
88	  const countsPerAlikeGroup = new Map<string, number>();
89	  for (const item of items) {
90	    countsPerAlikeGroup.set(item.type, (countsPerAlikeGroup.get(item.type) ?? 0) + 1);
91	  }
92	  return countsPerAlikeGroup;
93	}
94	
95	function qualifiesForComponentBlock(count: number): boolean {
96	  return count === COMPONENT_BLOCK_SIZE;
97	}
98	
99	function basePremiumForAlikeGroup(type: string, count: number): number {
100	  if (qualifiesForComponentBlock(count)) {
101	    return COMPONENT_BLOCK_BASE_PREMIUM;
102	  }
103	  return count * listedBasePremium(type);
104	}
105	
106	function isHighlyEnchanted(item: Item): boolean {
107	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
108	}
109	
110	// Item-specific modifiers apply to the base premium of the affected item,
111	// not to the policy total.
112	function itemSurcharges(item: Item): number {
113	  const itemBasePremium = listedBasePremium(item.type);
114	  let surcharges = 0;
115	  if (item.cursed === true) {
116	    surcharges += itemBasePremium * CURSE_SURCHARGE_RATE;
117	  }
118	  if (isHighlyEnchanted(item)) {
119	    surcharges += itemBasePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE;
120	  }
121	  return surcharges;
122	}
123	
124	// The spec's "policy base premium": the sum of all item base premiums,
125	// before any item-specific or policy-wide modifier.
126	function policyBasePremium(items: Item[]): number {
127	  let total = 0;
128	  for (const [type, count] of groupAlikeItems(items)) {
129	    total += basePremiumForAlikeGroup(type, count);
130	  }
131	  return total;
132	}
133	
134	function totalItemSurcharges(items: Item[]): number {
135	  return items.reduce((total, item) => total + itemSurcharges(item), 0);
136	}
137	
138	// How the customer stands with MHPCO when this policy is quoted. Loyalty and
139	// the follow-up discount both read this one history, so it travels as one value.
140	interface CustomerStanding {
141	  yearsWithMHPCO: number;
142	  previousContracts: number;
143	}
144	
145	function isLongStanding(standing: CustomerStanding): boolean {
146	  return standing.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
147	}
148	
149	// The spec's "each contract after their first": keyed on the customer's
150	// contract history, not on anything about this policy's items.
151	function isFollowUpContract(standing: CustomerStanding): boolean {
152	  return standing.previousContracts > 0;
153	}
154	
155	// Discounts MHPCO grants for who the customer is. Changes whenever MHPCO
156	// revises how it rewards customer history.
157	function customerStandingDiscounts(standing: CustomerStanding, basePremium: number): number {
158	  let discounts = 0;
159	  if (isLongStanding(standing)) {
160	    discounts += basePremium * LOYALTY_DISCOUNT_RATE;
161	  }
162	  if (isFollowUpContract(standing)) {
163	    discounts += basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE;
164	  }
165	  return discounts;
166	}
167	
168	// Every quote newly assesses the items it covers, so this surcharge applies to
169	// each policy regardless of the customer's standing (see the spec's second
170	// integration example). Changes independently of the history-based discounts.
171	function firstInsuranceSurcharge(basePremium: number): number {
172	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
173	}
174	
175	function roundPremiumInMHPCOsFavour(premium: number): number {
176	  return Math.ceil(premium);
177	}
178	
179	// The assessed premium for the items under this customer's standing, before
180	// MHPCO's fee. Every policy-wide modifier is a percentage of the policy base
181	// premium itself, never of the premium already raised by item-specific
182	// surcharges -- so they all scale `basePremium` and not a running total.
183	function assessedPremium(standing: CustomerStanding, items: Item[]): number {
184	  const basePremium = policyBasePremium(items);
185	  return (
186	    basePremium +
187	    totalItemSurcharges(items) +
188	    firstInsuranceSurcharge(basePremium) -
189	    customerStandingDiscounts(standing, basePremium)
190	  );
191	}
