193	// The fee is MHPCO's flat charge for handling the paperwork, not a risk
194	// modifier: it is added once the assessment is complete and no modifier
195	// scales it.
196	export function quote(customer: Customer, items: Item[], previousContracts = 0): number {
197	  const standing: CustomerStanding = { ...customer, previousContracts };
198	  return roundPremiumInMHPCOsFavour(assessedPremium(standing, items) + PROCESSING_FEE);
199	}
