201	function insuranceSum(items: Item[]): number {
202	  return items.reduce((sum, item) => sum + listedInsuranceValue(item.type), 0);
203	}
204	
205	function roundPayoutInMHPCOsFavour(payout: number): number {
206	  return Math.floor(payout);
207	}
