209	// The two special claim clauses are keyed on the damaged item, so each asks
210	// about the item the damage refers to.
211	function isVeryHighlyEnchanted(item: Item): boolean {
212	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
213	}
214	
215	function isMadeOfDragonMaterial(item: Item): boolean {
216	  return item.material === DRAGON_MATERIAL;
217	}
