219	// Which clause governs the damage, and what share of the damage amount it
220	// reimburses. The spec adjudicates the overlap -- a dragon-material item with
221	// enchantment >= 8 is reimbursed at 50 %, not fully -- so the high-enchantment
222	// clause is asked first. Dragon material grants full reimbursement, which is
223	// also what an item under no clause receives; the two rates are listed
224	// separately because MHPCO can revise the dragon clause without touching the
225	// standard treatment of ordinary items.
226	function reimbursementRateForDamagedItem(item: Item): number {
227	  if (isVeryHighlyEnchanted(item)) {
228	    return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
229	  }
230	  if (isMadeOfDragonMaterial(item)) {
231	    return DRAGON_MATERIAL_REIMBURSEMENT_RATE;
232	  }
233	  return NO_CLAUSE_REIMBURSEMENT_RATE;
234	}
235	
236	function coveredAmount(item: Item, damage: Damage): number {
237	  return damage.amount * reimbursementRateForDamagedItem(item);
238	}
239	
240	// A deductible applies per damage event, so each damaged item is reimbursed
241	// separately — clauses first, then the deductible — before the policy cap.
242	function reimbursementForDamage(item: Item, damage: Damage): number {
243	  return coveredAmount(item, damage) - DEDUCTIBLE_PER_DAMAGE;
244	}
245	
246	// A damage entry, resolved to the particular insured item it claims.
247	interface ClaimedDamage {
248	  item: Item;
249	  damage: Damage;
250	}
251	
252	// Whether MHPCO will assess a damage report at all, asked before the report is
253	// matched to an insured item: a negative amount is a malformed report rather
254	// than a claim with an answer. Changes when MHPCO revises what it accepts as a
255	// well-formed report, independently of how a report is matched to coverage.
256	function assertReportedAmount(damage: Damage): void {
257	  if (damage.amount < 0) {
258	    throw new Error(`damage to a ${damage.itemType} reports a negative amount: ${String(damage.amount)}`);
259	  }
260	}
261	
262	// Each damage entry is a separate damaged item, so a policy covering one sword
263	// cannot absorb two sword damages: every entry claims its own insured item,
264	// and a claimed item is no longer available to a later entry. Which item an
265	// entry claims -- and the rejection that follows from running out of matches --
266	// changes independently of what a claimed damage is reimbursed. An item type
267	// MHPCO does not insure is covered by no policy, so it is rejected here by the
268	// same "no insured item matches" decision rather than by a separate check.
269	function claimDamages(items: Item[], damages: Damage[]): ClaimedDamage[] {
270	  const unclaimed = [...items];
271	  return damages.map((damage) => {
272	    assertReportedAmount(damage);
273	    const index = unclaimed.findIndex((candidate) => candidate.type === damage.itemType);
274	    if (index === -1) {
275	      throw new Error(`the policy does not cover a damaged ${damage.itemType}`);
276	    }
277	    return { item: unclaimed.splice(index, 1)[0], damage };
278	  });
279	}
280	
281	function reimbursementForIncident(items: Item[], incident: Incident): number {
282	  return claimDamages(items, incident.damages).reduce(
283	    (total, { item, damage }) => total + reimbursementForDamage(item, damage),
284	    0,
285	  );
286	}
