326	// The spec's "total payout per policy is capped at twice the insurance sum":
327	// how much total exposure MHPCO accepts against the items' worth. Changes
328	// independently of what the items are worth (the price list) and of how an
329	// individual claim is limited by the cap still remaining.
330	function totalPayoutCap(items: Item[]): number {
331	  return insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
332	}
333	
334	function openPolicy(items: Item[]): Policy {
335	  return { items, remainingCap: totalPayoutCap(items) };
336	}
337	
338	// The cap decision, independent of which claim clauses produced the
339	// reimbursement: MHPCO never pays more than the policy's remaining cap, and
340	// whatever it pays is consumed from that cap.
341	function payoutAllowedByCap(reimbursement: number, remainingCap: number): ClaimResult {
342	  const payout = roundPayoutInMHPCOsFavour(Math.min(reimbursement, remainingCap));
343	  return { payout, remainingCap: remainingCap - payout };
344	}
345	
346	// Settling a claim composes two independently changing decisions: what the
347	// claim clauses reimburse, and how much of that the policy cap still allows.
348	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
349	  return payoutAllowedByCap(reimbursementForIncident(policy.items, incident), policy.remainingCap);
350	}
